)
AS dados
(
    codigo_inep,
    codigo_ies,
    nome,
    grau_academico,
    nivel_academico,
    modalidade,
    carga_horaria,
    situacao_inep,
    ano_censo
)

JOIN universidade ies
    ON ies.codigo =
        dados.codigo_ies

ON CONFLICT (codigo_inep)

DO UPDATE SET

    universidade_id =
        EXCLUDED.universidade_id,

    nome =
        EXCLUDED.nome,

    grau_academico =
        EXCLUDED.grau_academico,

    nivel_academico =
        EXCLUDED.nivel_academico,

    modalidade =
        EXCLUDED.modalidade,

    carga_horaria =
        EXCLUDED.carga_horaria,

    situacao_inep =
        EXCLUDED.situacao_inep,

    ano_censo =
        EXCLUDED.ano_censo,

    origem_dados =
        'INEP';


INSERT INTO curso
(
    codigo_inep,
    universidade_id,
    nome,
    grau_academico,
    nivel_academico,
    modalidade,
    carga_horaria,
    situacao_inep,
    ano_censo,
    origem_dados
)

SELECT

    dados.codigo_inep,
    ies.id,
    dados.nome,
    dados.grau_academico,
    dados.nivel_academico,
    dados.modalidade,
    dados.carga_horaria,
    dados.situacao_inep,
    dados.ano_censo,
