AS dados
(
    codigo_inep,
    codigo_ies,
    nome,
    grau_academico,
    nivel_academico,
    modalidade,
    carga_horaria,
    situacao_inep,
    ano_censo
)

JOIN universidade ies
    ON ies.codigo =
        dados.codigo_ies

ON CONFLICT (codigo_inep)

DO UPDATE SET

    universidade_id =
        EXCLUDED.universidade_id,

    nome =
        EXCLUDED.nome,

    grau_academico =
        EXCLUDED.grau_academico,

    nivel_academico =
        EXCLUDED.nivel_academico,

    modalidade =
        EXCLUDED.modalidade,

    carga_horaria =
        EXCLUDED.carga_horaria,

    situacao_inep =
