AS dados
(
    codigo_inep,
    codigo_ies,
    nome,
    grau_academico,
    nivel_academico,
    modalidade,
    carga_horaria,
    situacao_inep,
    ano_censo
)

JOIN universidade ies
    ON ies.codigo =
        dados.codigo_ies

ON CONFLICT (codigo_inep)

DO UPDATE SET

    universidade_id =
        EXCLUDED.universidade_id,

    nome =
        EXCLUDED.nome,

    grau_academico =
        EXCLUDED.grau_academico,

    nivel_academico =
        EXCLUDED.nivel_academico,

    modalidade =
        EXCLUDED.modalidade,

    carga_horaria =
        EXCLUDED.carga_horaria,

    situacao_inep =
        EXCLUDED.situacao_inep,

    ano_censo =
        EXCLUDED.ano_censo,

    origem_dados =
        'INEP';


COMMIT;


-- =========================================================
-- CONFERÊNCIA
-- =========================================================

SELECT
    COUNT(*) AS total_cursos
FROM curso
WHERE origem_dados = 'INEP';


SELECT
    grau_academico,
    COUNT(*) AS quantidade
FROM curso
WHERE origem_dados = 'INEP'
GROUP BY grau_academico
ORDER BY quantidade DESC;


SELECT
    modalidade,
    COUNT(*) AS quantidade
FROM curso
WHERE origem_dados = 'INEP'
GROUP BY modalidade
ORDER BY modalidade;


-- =========================================================
-- CURSOS DO IFAL
-- =========================================================

SELECT
    ies.nome AS instituicao,
    ies.sigla,
    c.codigo_inep,
    c.nome AS curso,
    c.grau_academico,
    c.modalidade,
    c.carga_horaria

FROM curso c

JOIN universidade ies
    ON ies.id =
        c.universidade_id

WHERE
    UPPER(
        COALESCE(
            ies.sigla,
            ''
        )
    ) = 'IFAL'

ORDER BY
    c.nome,
    c.modalidade;
